-- ---------------------------------------------------------------------------
-- Backfill: inherit parent years for year-less children (derived, NOT ETL data).
-- The ETL attached years to L3 directions but left the L4 inner directions
-- (ichki yo'nalish) year-less, whose admission years live on their L3 parent
-- (yo'nalish). This pass copies each L3 parent's years onto its year-less L4
-- children ONLY (hierarchy_level = 4). Higher levels are deliberately NOT
-- backfilled: a year-less L2/L3 row (the ~108 foreign "Xorijiy"/"Testlash" and
-- code-less NEEDS_REVIEW stragglers that the official Excel never carried) must
-- STAY year-less so a curator assigns the real admission year during review — it
-- must never inherit a coarse ancestor year (e.g. an L2 "Ta'lim sohasi" 2021
-- leaking onto an unreviewed L3 like "Ingliz tili va ...").
-- Idempotent: only L4 rows that currently have NO year, ON CONFLICT DO NOTHING.
-- Rollback: covered by this changeset's DELETE FROM h_speciality_year.
-- ---------------------------------------------------------------------------
SELECT c.id, py.year
FROM h_speciality c
JOIN h_speciality_year py ON py.speciality_id = c.parent_id
WHERE c.hierarchy_level = 4        -- ONLY L4 (ichki yo'nalish) inherits from its L3 parent
  AND c.parent_id IS NOT NULL
  AND NOT EXISTS (
      SELECT 1 FROM h_speciality_year cy WHERE cy.speciality_id = c.id
  )
ON CONFLICT (speciality_id, year) DO NOTHING;
